    ArrayList<InaccuracyType> list = new ArrayList<InaccuracyType>();
    if (InaccuracyTypeAccessor.isMove(entity)) {
        list.add(InaccuracyType.MOVE);
    }
    if (entity.m_20089_() == Pose.CROUCHING) {
