    }
    if (entity.m_20089_() == Pose.SWIMMING && !entity.m_6069_()) {
        list.add(InaccuracyType.LIE);
    }
    if (operator.getSynAimingProgress() >= 1.0f) {
        list.add(InaccuracyType.AIM);
    }
    return list;
}

